// Session 5 harness: the version switcher and the "Test conditions" panel.
// Do not edit this file. The code under review is in versions/a.js, b.js, c.js.

const VERSIONS = ['a', 'b', 'c'];
const modeLabel = document.querySelector('#mode');
const modeButtons = document.querySelectorAll('[data-mode]');

function showMode(mode) {
  modeLabel.textContent = mode;
  for (const button of modeButtons) {
    button.setAttribute('aria-pressed', String(button.dataset.mode === mode));
  }
}

async function refreshMode() {
  try {
    const res = await fetch('/__mode');
    showMode((await res.json()).mode);
  } catch {
    modeLabel.textContent = 'server not reachable — is node server.mjs running?';
  }
}

for (const button of modeButtons) {
  button.addEventListener('click', async () => {
    try {
      const res = await fetch('/__mode', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ mode: button.dataset.mode }),
      });
      showMode((await res.json()).mode);
    } catch {
      modeLabel.textContent = 'server not reachable — is node server.mjs running?';
    }
  });
}

refreshMode();

// ?v=a loads versions/a.js, and so on. Each version runs as soon as it loads.
const v = new URLSearchParams(location.search).get('v');
if (VERSIONS.includes(v)) {
  document.querySelector(`.menu a[href="?v=${v}"]`).setAttribute('aria-current', 'page');
  document.querySelector('#version-label').textContent = `— version ${v.toUpperCase()}`;
  document.title = `Catalogue — version ${v.toUpperCase()}`;
  import(`./versions/${v}.js`);
} else {
  document.querySelector('#status').textContent = 'Pick a version above: A, B or C.';
}
